+}
+template <>
+__device__ __forceinline__ float to_f<half>(half x) {
+  return __half2float(x);
+}
+
+__device__ __forceinline__ float sign_of(const int* bits, int i) {
+  return ((bits[i >> 5] >> (i & 31)) & 1) ? -1.0f : 1.0f;
