+  __shared__ __attribute__((aligned(16))) _Float16 sK[FRAGS * 2 * KT * X];
+  __shared__ __attribute__((aligned(16))) _Float16 sV[D * KT];
+  __shared__ __attribute__((aligned(16))) _Float16 sP[CW][16 * KT];
