+        const float mi = row16_max(sc);
+        const float mn = fmaxf(m_st[i], mi);
+        const float al = m_st[i] == -INFINITY ? 0.f : __expf(m_st[i] - mn);
+        p[i] = mn == -INFINITY ? 0.f : __expf(sc - mn);
