+  float l_state = 0.0f;
+  float o_acc = 0.0f;
+
+  for (int kv = start; kv < end; ++kv) {
+    const int lb = kv / block_size;
+    const int slot = kv - lb * block_size;
+    const int pb = block_table[req * max_blocks + lb];
+
+    // Load K nibble for my dimension
+    const int packed_idx = tid / 2;
