+    float partial = q_rot * k_val;
+    // Wave-level reduction (32 lanes)
+    partial += __shfl_xor(partial, 1);
+    partial += __shfl_xor(partial, 2);
+    partial += __shfl_xor(partial, 4);
+    partial += __shfl_xor(partial, 8);
+    partial += __shfl_xor(partial, 16);
