+    if (lane == 0) dot_lds[wave_id] = partial;
+    __syncthreads();
+
+    // Combine NW waves via tree reduction in first NW threads
+    float score = 0;
+    if (tid < NW) score = dot_lds[tid];
+  #pragma unroll
+    for (int s = 1; s < NW; s *= 2)
