+    o_acc += p * v_val;
+  }
+
+  // Store partial output + (m, l) for reduce stage
+  float* out_ptr = mid_o + qi * smo + hi * smh + si * sms;
+  out_ptr[tid] = o_acc;
+  if (tid == 0) {
+    out_ptr[HEAD_SIZE] = m_state;
+    out_ptr[HEAD_SIZE + 1] = l_state;
+  }
