+    float* out_ptr = mid_o + qi * smo + hi * smh + si * sms;
+    for (int d = 0; d < DIMS_PER_THREAD; ++d)
+      out_ptr[tid * DIMS_PER_THREAD + d] = 0.0f;
+    if (tid == 0) {
+      out_ptr[HEAD_SIZE] = -INFINITY;
+      out_ptr[HEAD_SIZE + 1] = 0.0f;
+    }
+    return;
+  }
