+  // Write output
+  float* out_ptr = mid_o + qi * smo + hi * smh + si * sms;
+  #pragma unroll
+  for (int d = 0; d < DIMS_PER_THREAD; ++d)
+    out_ptr[tid * DIMS_PER_THREAD + d] = o_vals[d];
+  if (tid == 0) {
+    out_ptr[HEAD_SIZE] = m_state;
+    out_ptr[HEAD_SIZE + 1] = l_state;
+  }
