+static bool wmma_arch_ok(const torch::Tensor& t) {
+  static const bool enabled = [] {
+    const char* e = std::getenv("VLLM_RDNA3_ATTN_WMMA");
+    return !(e && std::string(e) == "0");
+  }();
+  if (!enabled) return false;
