+    }
+  } else {
+    if (is_bf16) {
+      LAUNCH_RESHAPE(256, __hip_bfloat16);
+    } else {
+      LAUNCH_RESHAPE(256, half);
+    }
+  }
+  #undef LAUNCH_RESHAPE
+}
